def get_moves(state):
    moves = []
    for i, length in enumerate(state):
        for j in range(length - 1):
            # A tile covers squares at j and j+1 in the block of size length
            # The block is split into two blocks of size j and length-j-2
            new_block1 = j
            new_block2 = length - j - 2
            moves.append((i, new_block1, new_block2))
    return moves

memo = {}

def solve(state, is_alice):
    state = tuple(sorted([l for l in state if l > 0]))
    if not get_moves(state):
        return sum(state)

    state_key = (state, is_alice)
    if state_key in memo:
        return memo[state_key]

    moves = get_moves(state)
    if is_alice:
        res = -float('inf')
        for i, b1, b2 in moves:
            new_state = list(state)
            new_state.pop(i)
            if b1 > 0:
                new_state.append(b1)
            if b2 > 0:
                new_state.append(b2)
            res = max(res, solve(tuple(new_state), False))
        memo[state_key] = res
        return res
    else:
        res = float('inf')
        for i, b1, b2 in moves:
            new_state = list(state)
            new_state.pop(i)
            if b1 > 0:
                new_state.append(b1)
            if b2 > 0:
                new_state.append(b2)
            res = min(res, solve(tuple(new_state), True))
        memo[state_key] = res
        return res

